// 작성자 송예찬 · 의사코드: 확대한 포드와 방, 생활 가구, 외부 경비의 기하를 검사하고 기존 이동 설정을 보존한다.
// 코딩
using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class HabitatVerification {
 static bool Close(Vector3 actual,JToken before)=>Vector3.Distance(actual,new Vector3((float)before[0],(float)before[1],(float)before[2]))<.00003f;
 public static string Main(){var all=HabitatSession.All();var pod=HabitatSession.Pod;var old=JArray.Parse(File.ReadAllText(Path.Combine(HabitatSession.W,"live_components_before.json")));var cc=all.SelectMany(t=>t.GetComponents<CharacterController>()).Single();string player=HabitatSession.P(cc.transform);var protectedChanges=new List<string>();foreach(var record in old){string path=(string)record["path"];if(path.Contains("/Room01_Isolation/")||path==HabitatSession.P(HabitatSession.Room)||path==player||path.StartsWith(player+"/")||path.StartsWith("Camera/"))continue;var t=all.FirstOrDefault(a=>a.GetInstanceID()==(int)record["id"]);if(!t)t=all.Where(a=>HabitatSession.P(a)==path).OrderBy(a=>Vector3.Distance(a.localPosition,new Vector3((float)record["localPos"][0],(float)record["localPos"][1],(float)record["localPos"][2]))).FirstOrDefault();if(!t){protectedChanges.Add(path+" missing");continue;}var q=record["rot"].ToObject<float[]>();if(!Close(t.localPosition,record["localPos"])||!Close(t.localScale,record["scale"])||Quaternion.Angle(t.localRotation,new Quaternion(q[0],q[1],q[2],q[3]))>.001f)protectedChanges.Add(path);}
 int scripts=all.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject));var brokenMesh=all.SelectMany(t=>t.GetComponents<MeshFilter>()).Where(m=>m.sharedMesh==null).Select(m=>HabitatSession.P(m.transform)).ToArray();var brokenMaterial=all.SelectMany(t=>t.GetComponents<Renderer>()).Where(r=>r.enabled&&r.sharedMaterials.Any(m=>m==null||m.shader==null||m.shader.name=="Hidden/InternalErrorShader")).Select(r=>HabitatSession.P(r.transform)).ToArray();var guard=all.First(t=>t.name.StartsWith("Guard_A_"));var gb=HabitatSession.B(guard.gameObject);bool outside=gb.max.z<pod.position.z-3.99f-.4f;
 var center=cc.transform.TransformPoint(cc.center);var low=center-Vector3.up*(cc.height*.5f-cc.radius);var high=center+Vector3.up*(cc.height*.5f-cc.radius);Physics.SyncTransforms();var overlaps=Physics.OverlapCapsule(low,high,cc.radius).Where(c=>c!=cc).Select(c=>HabitatSession.P(c.transform)).ToArray();var floor=Physics.RaycastAll(new Vector3(cc.transform.position.x,1.5f,cc.transform.position.z),Vector3.down,3).Where(h=>h.collider.transform.name=="HabitatFloor_Collision").ToArray();bool floorAligned=floor.Length>0&&Mathf.Abs(floor[0].point.y-.28f)<.001f;
 var furnishings=HabitatSession.Room.Find("Habitat_LivingArea").Cast<Transform>().Concat(new[]{all.First(t=>t.name.StartsWith("P01_IsolationBunk"))}).Select(t=>{var b=HabitatSession.B(t.gameObject);float max=0;foreach(float x in new[]{b.min.x,b.max.x})foreach(float z in new[]{b.min.z,b.max.z})max=Mathf.Max(max,new Vector2(x-pod.position.x,z-pod.position.z).magnitude);return new{name=t.name,maxCornerRadius=max,inside=max<3.906f,bottom=b.min.y};}).ToArray();
 var start=cc.transform.position;var moves=new List<object>();bool movesPass=true;try{for(int i=0;i<8;i++){cc.enabled=false;cc.transform.position=start;cc.enabled=true;Physics.SyncTransforms();var direction=Quaternion.Euler(0,i*45,0)*Vector3.forward;for(int j=0;j<100;j++)cc.Move(direction*.055f);float radius=new Vector2(cc.transform.position.x-pod.position.x,cc.transform.position.z-pod.position.z).magnitude;bool pass=radius<3.75f;movesPass&=pass;moves.Add(new{angle=i*45,radius=radius,stoppedInside=pass});}}finally{cc.enabled=false;cc.transform.position=start;cc.enabled=true;Physics.SyncTransforms();}
 bool scale=(pod.localScale-new Vector3(3,2,3)).sqrMagnitude<.000001f;bool pos=(pod.localPosition-new Vector3(0,0,10.32f)).sqrMagnitude<.000001f;var ceiling=all.SelectMany(t=>t.GetComponents<Renderer>()).Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&HabitatSession.P(r.transform).Contains("Room01_Isolation/")&&HabitatSession.P(r.transform).Contains("Ceiling")).ToArray();float ceilingBottom=ceiling.Min(r=>r.bounds.min.y);bool roomClear=ceilingBottom>7.19f&&HabitatSession.B(pod.gameObject).max.y<ceilingBottom-.5f;
 bool passAll=protectedChanges.Count==0&&scripts==0&&brokenMesh.Length==0&&brokenMaterial.Length==0&&outside&&overlaps.Length==0&&floorAligned&&furnishings.All(f=>f.inside)&&movesPass&&scale&&pos&&roomClear;var result=new{pass=passAll,protectedTransformsChanged=protectedChanges,missingScripts=scripts,brokenMeshes=brokenMesh,brokenMaterials=brokenMaterial,userPodScalePreserved=scale,userPodPositionPreserved=pos,guardOutsideGlass=outside,guardPosition=HabitatSession.V(guard.position),spawnOverlaps=overlaps,floorRaycastAligned=floorAligned,spawn=HabitatSession.V(start),ceilingUnderside=ceilingBottom,ceilingGap=ceilingBottom-HabitatSession.B(pod.gameObject).max.y,furnishings=furnishings,movementChecks=moves,note="Editor collision and layout review; not a full keyboard/puzzle playtest"};File.WriteAllText(Path.Combine(HabitatSession.W,"habitat_verification.json"),JsonConvert.SerializeObject(result,Formatting.Indented));if(!passAll)throw new Exception("Habitat check failed; inspect habitat_verification.json");return "User scale/position preserved, guard outside, furniture inside, floor/8 movement checks and protected transforms verified";}
}
// 주석: 임시 이동은 항상 원래 시작 Transform으로 복원한다. 문 개폐 입력이나 게임 기능을 만들지 않는다.
